const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('.main-nav');toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open);document.body.classList.toggle('menu-open',!open)});document.querySelectorAll('.main-nav a').forEach(a=>{if(a.pathname===location.pathname||(a.pathname!=='/'&&location.pathname.startsWith(a.pathname)))a.classList.add('active');a.addEventListener('click',()=>{toggle?.setAttribute('aria-expanded','false');nav?.classList.remove('open');document.body.classList.remove('menu-open')})});const obs=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>obs.observe(e));document.querySelectorAll('[data-year]').forEach(e=>e.textContent=new Date().getFullYear());document.querySelector('#service-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('[data-filter-grid] .service-card').forEach(c=>c.hidden=q&&!c.textContent.toLowerCase().includes(q))});const requested=new URLSearchParams(location.search).get('service');if(requested)document.querySelectorAll('select[name="service"]').forEach(s=>{const o=[...s.options].find(x=>x.text===requested);if(o)s.value=o.value});document.querySelectorAll('.whatsapp-form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const d=new FormData(form),rows=[['Name',d.get('name')],['Company',d.get('company')],['Phone',d.get('phone')],['Email',d.get('email')],['Location',d.get('location')],['Service',d.get('service')],['Dimensions / quantity',d.get('dimensions')],['Timeframe',d.get('timeframe')],['Project brief',d.get('details')]].filter(x=>x[1]);const file=form.querySelector('input[type="file"]')?.files?.[0];if(file)rows.push(['Reference file to attach',file.name]);const message=['Hello MahrajArabia, I would like to request a quotation.','',...rows.map(x=>`${x[0]}: ${x[1]}`),...(file?['','I will attach this file in WhatsApp.']:[])].join('\n');form.querySelector('.form-status').textContent='Opening WhatsApp with your project details…';window.open(`https://wa.me/${form.dataset.destination}?text=${encodeURIComponent(message)}`,'_blank','noopener')}));
